35	Chunk ArrowBlockInputFormat::read()
36	{
37	    Chunk res;
38	    block_missing_values.clear();
39	    arrow::Result<std::shared_ptr<arrow::RecordBatch>> batch_result;
40	    size_t batch_start = getDataOffsetMaybeCompressed(*in);
41	    if (stream)
42	    {
43	        if (!stream_reader)
44	            prepareReader();
45	
46	        if (is_stopped)
47	            return {};
48	
49	        batch_result = stream_reader->Next();
50	        if (batch_result.ok() && !(*batch_result))
51	        {
52	            /// Make sure we try to read past the end to fully drain the ReadBuffer (e.g. read
53	            /// compression frame footer or HTTP chunked encoding's final empty chunk).
54	            /// This is needed for HTTP keepalive.
55	            in->eof();
56	
57	            return res;
58	        }
59	
60	        if (need_only_count && batch_result.ok())
61	            return getChunkForCount((*batch_result)->num_rows());
62	    }
63	    else
64	    {
65	        if (!file_reader)
66	            prepareReader();
67	
68	        if (is_stopped)
69	            return {};
70	
71	        if (record_batch_current >= record_batch_total)
72	        {
73	            in->eof();
74	            return res;
75	        }
76	
77	        if (need_only_count)
78	        {
79	            auto rows = file_reader->RecordBatchCountRows(record_batch_current++);
80	            if (!rows.ok())
81	                throw Exception(
82	                    ErrorCodes::CANNOT_READ_ALL_DATA, "Error while reading batch of Arrow data: {}", rows.status().ToString());
83	            return getChunkForCount(*rows);
84	        }
85	
86	        batch_result = file_reader->ReadRecordBatch(record_batch_current);
87	    }
88	
89	    if (!batch_result.ok())
90	        throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA,
91	            "Error while reading batch of Arrow data: {}", batch_result.status().ToString());
92	
93	    auto table_result = arrow::Table::FromRecordBatches({*batch_result});
94	    if (!table_result.ok())
95	        throw Exception(ErrorCodes::CANNOT_READ_ALL_DATA,
96	            "Error while reading batch of Arrow data: {}", table_result.status().ToString());
97	
98	    ++record_batch_current;
99	
100	    /// If defaults_for_omitted_fields is true, calculate the default values from default expression for omitted fields.
101	    /// Otherwise fill the missing columns with zero values of its type.
102	    BlockMissingValues * block_missing_values_ptr = format_settings.defaults_for_omitted_fields ? &block_missing_values : nullptr;
