142	static std::shared_ptr<arrow::ipc::RecordBatchFileReader> createFileReader(ReadBuffer & in, const FormatSettings & format_settings, std::atomic<int> & is_stopped)
143	{
144	    auto arrow_file = asArrowFile(in, format_settings, is_stopped, "Arrow", ARROW_MAGIC_BYTES);
145	    if (is_stopped)
146	        return nullptr;
147	
148	    auto options = arrow::ipc::IpcReadOptions::Defaults();
149	    options.memory_pool = ArrowMemoryPool::instance();
