namespace
{

/// Recursive validation of the physical layout of an arrow::ArrayData against the
/// lengths and offsets declared in the (potentially malicious) input file.
///
/// The Arrow IPC reader trusts the RecordBatch/FieldNode metadata: a crafted file can
/// declare a row count that is larger than the actual data/offsets/validity buffers can
/// hold, which later leads to heap out-of-bounds reads while we copy the data into
/// ClickHouse columns (and even earlier, when Arrow itself scans the validity bitmap to
/// compute the null count). We reject such input with INCORRECT_DATA *before* the arrow
/// table is built and before any column memory is reserved.

[[noreturn]] void throwIncorrectData(const std::string & column_name, const std::string & message)
{
    throw Exception(
        ErrorCodes::INCORRECT_DATA,
        "Malformed Arrow data for column '{}': {}",
        column_name,
        message);
}

/// Checked int64 arithmetic. Any overflow means the declared length/offset can not be
/// backed by a real buffer, so we treat it as corrupted data rather than letting a huge
/// (or wrapped-to-zero) allocation size slip through.
Int64 checkedAdd(Int64 a, Int64 b, const std::string & column_name)
{
    Int64 result;
    if (common::addOverflow(a, b, result))
        throwIncorrectData(column_name, "integer overflow while validating buffer sizes");
    return result;
}

Int64 checkedMul(Int64 a, Int64 b, const std::string & column_name)
{
    Int64 result;
    if (common::mulOverflow(a, b, result))
        throwIncorrectData(column_name, "integer overflow while validating buffer sizes");
    return result;
}

Int64 bitmapBytes(Int64 num_bits, const std::string & column_name)
{
    /// ceil(num_bits / 8)
    return checkedAdd(num_bits, 7, column_name) / 8;
}

Int64 bufferSize(const std::shared_ptr<arrow::Buffer> & buffer)
{
    return buffer ? static_cast<Int64>(buffer->size()) : 0;
}

void validateArrowArrayData(const arrow::ArrayData & data, const std::string & column_name);

/// buffers[0] (when present) is the validity bitmap and must cover offset + length bits.
/// This must hold for every column, including nested (list/struct/map) children that were
/// sliced or flattened, otherwise Arrow's own null-count computation would read past the
/// end of a truncated bitmap.
void validateValidityBitmap(const arrow::ArrayData & data, const std::string & column_name)
{
    if (data.buffers.empty() || data.buffers[0] == nullptr)
        return;

    const Int64 num_bits = checkedAdd(data.offset, data.length, column_name);
    const Int64 needed = bitmapBytes(num_bits, column_name);
    if (bufferSize(data.buffers[0]) < needed)
        throwIncorrectData(
            column_name,
            fmt::format(
                "validity bitmap is too small: need {} bytes to cover {} rows, but buffer is {} bytes",
                needed,
                data.length,
                bufferSize(data.buffers[0])));
}

/// Fixed-width values buffer (numeric, decimal, date/time, duration, fixed size binary, ...).
void validateFixedWidthBuffer(const arrow::ArrayData & data, const std::string & column_name, Int64 byte_width)
{
