201	template <typename OffsetType>
202	void validateBinaryLikeBuffers(const arrow::ArrayData & data, const std::string & column_name)
203	{
204	    /// The readers iterate over rows in [0, length) and only then dereference value_offset(i)
205	    /// / value_length(i), so a zero-length column never touches the offsets buffer (which some
206	    /// writers emit as an empty buffer for empty columns).
207	    if (data.length == 0)
208	        return;
209	
210	    const Int64 num_offsets = checkedAdd(checkedAdd(data.offset, data.length, column_name), 1, column_name);
211	    const Int64 needed_offsets_bytes = checkedMul(num_offsets, static_cast<Int64>(sizeof(OffsetType)), column_name);
212	    if (data.buffers.size() < 2 || bufferSize(data.buffers[1]) < needed_offsets_bytes)
213	        throwIncorrectData(
214	            column_name,
215	            fmt::format(
216	                "offsets buffer is too small: need {} bytes to hold {} rows, but buffer is {} bytes",
217	                needed_offsets_bytes,
218	                data.length,
219	                data.buffers.size() < 2 ? 0 : bufferSize(data.buffers[1])));
220	
221	    const Int64 values_size = data.buffers.size() < 3 ? 0 : bufferSize(data.buffers[2]);
222	    const auto * offsets = reinterpret_cast<const OffsetType *>(data.buffers[1]->data());
223	    for (Int64 i = 0; i < data.length; ++i)
224	    {
225	        const Int64 begin = static_cast<Int64>(offsets[data.offset + i]);
226	        const Int64 end = static_cast<Int64>(offsets[data.offset + i + 1]);
227	        if (begin < 0 || end < begin || end > values_size)
228	            throwIncorrectData(
229	                column_name,
230	                fmt::format(
231	                    "value offsets exceed data buffer bounds: row {} spans [{}, {}) but data buffer is {} bytes",
232	                    i,
233	                    begin,
234	                    end,
235	                    values_size));
236	    }
